17	        BigDecimal outstanding = invoices.findAll().stream()
18	                .filter(invoice -> "SENT".equals(invoice.getStatus()))
19	                .map(Invoice::getAmount)
20	                .reduce(BigDecimal.ZERO, BigDecimal::add);
21	        response.send(new DashboardView(clients.count(), projects.count(), outstanding));
