1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // invoices references projects references clients, so H2 refuses to TRUNCATE a parent while
36	        // the FK exists — drop referential integrity for the duration, truncate all, then restore.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
40	            jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE invoice_payments RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
45	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
46	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
47	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
48	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
49	        } finally {
50	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
51	        }
52	    }
53	
54	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
55	    @PostMapping("/seed")
56	    @SuppressWarnings("unchecked")
57	    public void seed(@RequestBody Map<String, Object> fixture) {
58	        List<Map<String, Object>> clients =
59	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
60	        // Explicit ids from the fixture (the spec asserts rows by these ids), via JdbcTemplate.
61	        for (Map<String, Object> c : clients) {
62	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
63	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
64	        }
65	        List<Map<String, Object>> projects =
66	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
67	        for (Map<String, Object> p : projects) {
68	            // status is optional in the fixture — a spec that only cares a project exists leaves it
69	            // out, defaulting to ACTIVE (the same state a fresh project gets, V22__project_status.sql).
70	            Object status = p.getOrDefault("status", "ACTIVE");
71	            // archived is optional too — a spec that only cares a project exists leaves it out,
72	            // defaulting to not-archived (the same state a fresh project gets, V16__project_archived.sql).
73	            boolean archived = Boolean.TRUE.equals(p.getOrDefault("archived", Boolean.FALSE));
74	            // budget is optional in the fixture — a spec that does not care about the budget leaves
75	            // it out, so the column stays NULL (the same state a fresh project gets until one is set,
76	            // V23__project_budget.sql).
77	            java.math.BigDecimal budget = p.get("budget") != null
78	                    ? new java.math.BigDecimal(p.get("budget").toString())
79	                    : null;
80	            jdbc.update(
81	                    "INSERT INTO projects (id, name, client_id, status, archived, budget)"
82	                            + " VALUES (?, ?, ?, ?, ?, ?)",
83	                    ((Number) p.get("id")).longValue(), p.get("name"),
84	                    ((Number) p.get("clientId")).longValue(), status.toString(), archived, budget);
85	        }
86	        List<Map<String, Object>> contacts =
87	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
88	        for (Map<String, Object> c : contacts) {
89	            jdbc.update(
90	                    "INSERT INTO contacts (id, name, email, contact_role, client_id)"
91	                            + " VALUES (?, ?, ?, ?, ?)",
92	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"),
93	                    c.get("role"), ((Number) c.get("clientId")).longValue());
94	        }
95	        List<Map<String, Object>> invoices =
96	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
97	        for (Map<String, Object> inv : invoices) {
98	            Object status = inv.getOrDefault("status", "DRAFT");
99	            // Dates are optional in the fixture — a spec that only cares about the lifecycle leaves
100	            // them out, so default issued=today / due=+30 days (the same rule CreateInvoice applies).
101	            java.time.LocalDate issued = inv.get("issuedDate") != null
102	                    ? java.time.LocalDate.parse(inv.get("issuedDate").toString())
103	                    : java.time.LocalDate.now();
104	            java.time.LocalDate due = inv.get("dueDate") != null
105	                    ? java.time.LocalDate.parse(inv.get("dueDate").toString())
106	                    : issued.plusDays(30);
107	            // An invoice is built from line items; its amount is the sum of each line's qty times
108	            // unit price. A fixture gives the lines (not a figure), so compute the amount from them
109	            // here — the same derivation CreateLineItem keeps in step on every add. A legacy fixture
110	            // that still supplies an explicit amount (and no lines) is honoured as-is.
111	            List<Map<String, Object>> lineItems =
112	                    (List<Map<String, Object>>) inv.getOrDefault("lineItems", List.of());
113	            java.math.BigDecimal amount;
114	            if (inv.get("amount") != null) {
115	                amount = new java.math.BigDecimal(inv.get("amount").toString());
116	            } else {
117	                amount = java.math.BigDecimal.ZERO;
118	                for (Map<String, Object> li : lineItems) {
119	                    amount = amount.add(new java.math.BigDecimal(li.get("unitPrice").toString())
120	                            .multiply(new java.math.BigDecimal(li.get("qty").toString())));
121	                }
122	            }
123	            jdbc.update(
124	                    "INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
125	                            + " VALUES (?, ?, ?, ?, ?, ?)",
126	                    ((Number) inv.get("id")).longValue(),
127	                    ((Number) inv.get("projectId")).longValue(),
128	                    amount,
129	                    status.toString(),
130	                    java.sql.Date.valueOf(issued),
131	                    java.sql.Date.valueOf(due));
132	            // Insert the invoice's lines with their explicit fixture ids (the spec asserts rows by
133	            // these ids), owned by this invoice.
134	            for (Map<String, Object> li : lineItems) {
135	                jdbc.update(
136	                        "INSERT INTO invoice_line_items"
137	                                + " (id, invoice_id, description, quantity, unit_price)"
138	                                + " VALUES (?, ?, ?, ?, ?)",
139	                        ((Number) li.get("id")).longValue(),
140	                        ((Number) inv.get("id")).longValue(),
141	                        li.get("description"),
142	                        ((Number) li.get("qty")).intValue(),
143	                        new java.math.BigDecimal(li.get("unitPrice").toString()));
144	            }
145	        }
146	        // Payments a client has made against an invoice (amount + the date paid), with their
147	        // explicit fixture ids (the spec asserts rows by these ids), owned by a seeded invoice.
148	        List<Map<String, Object>> payments =
149	                (List<Map<String, Object>>) fixture.getOrDefault("payments", List.of());
150	        long maxPaymentId = 0;
151	        for (Map<String, Object> pay : payments) {
152	            long paymentId = ((Number) pay.get("id")).longValue();
153	            jdbc.update(
154	                    "INSERT INTO invoice_payments (id, invoice_id, amount, paid_date)"
155	                            + " VALUES (?, ?, ?, ?)",
156	                    paymentId,
157	                    ((Number) pay.get("invoiceId")).longValue(),
158	                    new java.math.BigDecimal(pay.get("amount").toString()),
159	                    java.sql.Date.valueOf(
160	                            java.time.LocalDate.parse(pay.get("date").toString())));
161	            maxPaymentId = Math.max(maxPaymentId, paymentId);
162	        }
163	        // Explicit ids (GENERATED BY DEFAULT) do NOT advance H2's identity sequence, so a payment
164	        // recorded through the API would collide on id 1. Bump the sequence past the seeded rows.
165	        if (maxPaymentId > 0) {
166	            jdbc.execute(
167	                    "ALTER TABLE invoice_payments ALTER COLUMN id RESTART WITH " + (maxPaymentId + 1));
168	        }
